import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from sampling ----
type Point = [number, number];

/** mulberry32: a fixed seed keeps every sampler identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** Every sampler runs in a box 1 unit wide and `boxHeight` tall, so a resize only rescales. */
const BOX_HEIGHT = 0.55;
const PANEL_HEIGHT = 0.42;

function nearest(points: Point[], x: number, y: number): Point {
  let best = points[0];
  let bestDistance = Infinity;
  for (const p of points) {
    const distance = (p[0] - x) * (p[0] - x) + (p[1] - y) * (p[1] - y);
    if (distance < bestDistance) {
      bestDistance = distance;
      best = p;
    }
  }
  return best;
}

/** Independent uniform draws: the sampler that clumps and leaves gaps. */
function uniformSamples(count: number, seed: number, boxHeight = BOX_HEIGHT): Point[] {
  const random = seededRandom(seed);
  return Array.from({ length: count }, () => [random(), random() * boxHeight] as Point);
}

type Candidate = { point: Point; nearest: Point; isBest: boolean };
type BestCandidateStep = { point: Point; candidates: Candidate[] };

/** Mitchell's best-candidate: each sample is the one of k draws farthest from its nearest neighbour. */
function bestCandidateSteps(
  count: number,
  k: number,
  seed: number,
  boxHeight = BOX_HEIGHT
): BestCandidateStep[] {
  const random = seededRandom(seed);
  const placed: Point[] = [[random(), random() * boxHeight]];
  const steps: BestCandidateStep[] = [{ point: placed[0], candidates: [] }];

  for (let i = 1; i < count; ++i) {
    const candidates: Candidate[] = [];
    let bestIndex = 0;
    let bestDistance = -1;

    for (let j = 0; j < k; ++j) {
      const point: Point = [random(), random() * boxHeight];
      const near = nearest(placed, point[0], point[1]);
      const distance = Math.hypot(near[0] - point[0], near[1] - point[1]);
      if (distance > bestDistance) {
        bestDistance = distance;
        bestIndex = j;
      }
      candidates.push({ point, nearest: near, isBest: false });
    }

    candidates[bestIndex].isBest = true;
    placed.push(candidates[bestIndex].point);
    steps.push({ point: candidates[bestIndex].point, candidates });
  }

  return steps;
}

type PoissonStep = { point: Point; parent: Point | null };
type PoissonRun = {
  steps: PoissonStep[];
  radius: number;
  cellSize: number;
  gridWidth: number;
  gridHeight: number;
};

/**
 * Bridson's algorithm: a background grid of cells smaller than radius/sqrt(2) holds at most one
 * sample each, so the minimum-distance test only ever reads a 5x5 neighbourhood.
 */
function poissonDiscSamples(
  radius: number,
  seed: number,
  boxHeight = BOX_HEIGHT,
  k = 30
): PoissonRun {
  const random = seededRandom(seed);
  const radius2 = radius * radius;
  const annulus = 3 * radius2;
  const cellSize = radius * Math.SQRT1_2;
  const gridWidth = Math.ceil(1 / cellSize);
  const gridHeight = Math.ceil(boxHeight / cellSize);
  const grid: (Point | undefined)[] = new Array(gridWidth * gridHeight);
  const active: Point[] = [];
  const steps: PoissonStep[] = [];

  // Cells are radius/sqrt(2) wide, so any conflicting sample sits within two cells: scan the
  // 5x5 block of offsets around the candidate's cell, skipping offsets that leave the grid.
  const crowded = (x: number, y: number): boolean => {
    const column = Math.floor(x / cellSize);
    const row = Math.floor(y / cellSize);
    for (let rowOffset = -2; rowOffset <= 2; rowOffset++) {
      const r = row + rowOffset;
      if (r < 0 || r >= gridHeight) continue;
      for (let columnOffset = -2; columnOffset <= 2; columnOffset++) {
        const c = column + columnOffset;
        if (c < 0 || c >= gridWidth) continue;
        const neighbour = grid[r * gridWidth + c];
        if (!neighbour) continue;
        const dx = neighbour[0] - x;
        const dy = neighbour[1] - y;
        if (dx * dx + dy * dy < radius2) return true;
      }
    }
    return false;
  };

  const emit = (x: number, y: number, parent: Point | null) => {
    const s: Point = [x, y];
    active.push(s);
    grid[gridWidth * (y / cellSize | 0) + (x / cellSize | 0)] = s;
    steps.push({ point: s, parent });
  };

  emit(random(), random() * boxHeight, null);

  while (active.length) {
    const index = (random() * active.length) | 0;
    const s = active[index];
    let placed = false;

    for (let j = 0; j < k && !placed; ++j) {
      const angle = 2 * Math.PI * random();
      const r = Math.sqrt(random() * annulus + radius2);
      const x = s[0] + r * Math.cos(angle);
      const y = s[1] + r * Math.sin(angle);
      if (x >= 0 && x < 1 && y >= 0 && y < boxHeight && !crowded(x, y)) {
        emit(x, y, s);
        placed = true;
      }
    }

    // Exhausting k candidates retires the sample: nothing more fits around it.
    if (!placed) {
      active[index] = active[active.length - 1];
      active.pop();
    }
  }

  return { steps, radius, cellSize, gridWidth, gridHeight };
}

const uniformPoints = uniformSamples(700, 20260813);
const bestCandidateRun = bestCandidateSteps(300, 8, 20260814);
const poissonRun = poissonDiscSamples(0.032, 20260815);

/** The comparison panels share a point count, taken from whatever Poisson-disc yields. */
const comparisonPoisson = poissonDiscSamples(0.055, 20260816, PANEL_HEIGHT);
const comparisonCount = comparisonPoisson.steps.length;

const comparisonSets: { label: string; points: Point[] }[] = [
  { label: 'Uniform random', points: uniformSamples(comparisonCount, 20260817, PANEL_HEIGHT) },
  {
    label: 'Best candidate',
    points: bestCandidateSteps(comparisonCount, 8, 20260818, PANEL_HEIGHT).map((s) => s.point)
  },
  { label: 'Poisson disc', points: comparisonPoisson.steps.map((s) => s.point) }
];

const PAD = 6;
const LABEL_HEIGHT = 18;
const GAP = 10;

type Cell = { path: string; area: number };

export default function SamplingVoronoi({ width }: { width: number }) {
  const scale = Math.max(1, width - PAD * 2);
  const panelHeight = scale * PANEL_HEIGHT;
  const height = Math.round(
    PAD * 2 + comparisonSets.length * (LABEL_HEIGHT + panelHeight) + GAP * (comparisonSets.length - 1)
  );

  const { panels, color } = useMemo(() => {
    const panels = comparisonSets.map(({ label, points }) => {
      const scaled = points.map((p) => [p[0] * scale, p[1] * scale] as [number, number]);
      const voronoi = d3.Delaunay.from(scaled).voronoi([0, 0, scale, panelHeight]);
      const cells: Cell[] = scaled.map((_, i) => {
        const polygon = voronoi.cellPolygon(i);
        return {
          path: polygon ? `M${polygon.join('L')}Z` : '',
          area: polygon ? Math.abs(d3.polygonArea(polygon)) : 0
        };
      });
      return { label, cells };
    });

    // One colour domain across all three panels, so cell area is comparable between them.
    const areas = panels.flatMap((panel) => panel.cells.map((c) => c.area)).sort(d3.ascending);
    const color = d3
      .scaleSequential(d3.interpolateViridis)
      .domain([d3.quantile(areas, 0.02) ?? 0, d3.quantile(areas, 0.98) ?? 1])
      .clamp(true);

    return { panels, color };
  }, [scale, panelHeight]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Three sampling methods compared by Voronoi cell area at the same point count: uniform random varies wildly, best candidate is tighter, and Poisson-disc cells are nearly uniform"
    >
      {panels.map((panel, p) => (
        <g key={panel.label} transform={`translate(${PAD},${PAD + p * (LABEL_HEIGHT + panelHeight + GAP)})`}>
          <text y={12} fontSize={11} fill="var(--muted)">
            {panel.label}
          </text>
          <g transform={`translate(0,${LABEL_HEIGHT})`}>
            {panel.cells.map((c, i) => (
              <path key={i} d={c.path} fill={color(c.area)} stroke="var(--bg)" strokeWidth={0.5} />
            ))}
            <rect width={scale} height={panelHeight} fill="none" stroke="var(--line)" />
          </g>
        </g>
      ))}
    </svg>
  );
}
